import sys
M=1000000007
P=2*(M+1)
def f(n):
    a=0;b=1
    for c in bin(n%P)[2:]:
        x=a*((b<<1)-a)%M
        y=(a*a+b*b)%M
        z=(x+y)%M
        if c=='1':
            a=y;b=z
        else:
            a=x;b=y
    return a
def main():
    out=[]
    for s in sys.stdin.read().split():
        out.append(str(f(int(s))))
    sys.stdout.write("\n".join(out)+"\n")
main()
